def populate_questionnaire_hash(apps, schema_editor):
    Questionnaire = apps.get_model("emr", "Questionnaire")
    for questionnaire in Questionnaire.objects.all():
        current_obj_questions = json.dumps(
            questionnaire.questions, sort_keys=True
        ).encode("utf-8")
        current_obj_hash = hashlib.sha256(current_obj_questions).hexdigest()
        questionnaire.questions_hash = current_obj_hash
        questionnaire.save(update_fields=["questions_hash"])


def backfill_child_flags(apps, schema_editor):
    location = apps.get_model("emr", "FacilityLocation")
    locations = location.objects.using(schema_editor.connection.alias)
    children = locations.filter(parent_id=OuterRef("pk"), deleted=False)
    locations.update(
        has_children=Exists(children),
        has_sub_locations=Exists(children.filter(mode="kind")),
        has_beds=Exists(children.filter(mode="instance")),
        cached_parent_json={},
    )


def migrate_specimen_definition_collection(apps, schema_editor):
    specimen_definition = apps.get_model("emr", "SpecimenDefinition")
    updates = []
    for definition in specimen_definition.objects.all():
        collection = definition.collection
        if not collection:
            continue
        definition.collection = {"code": collection}
        updates.append(definition)
    if updates:
        specimen_definition.objects.bulk_update(updates, ["collection"])


